import { configureStore, combineReducers } from '@reduxjs/toolkit';
import { persistStore, persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage';

import authReducer from './features/auth/authSlice';
import todosReducer from './features/todos/todosSlice';

const rootReducer = combineReducers({
  auth: authReducer,
  todos: todosReducer,
});

const persistConfig = {
  key: 'root',
  version: 1,
  storage,
};

const persistedReducer = persistReducer(persistConfig, rootReducer);

export const store = configureStore({
  reducer: persistedReducer,
});

export const persistor = persistStore(store);

import { Provider } from 'react-redux';
import { PersistGate } from 'redux-persist/integration/react';
import { store, persistor } from './app/store';
import App from './App';

function Root() {
  return (
    <Provider store={store}>
      <PersistGate loading={<div>Loading…</div>} persistor={persistor}>
        <App />
      </PersistGate>
    </Provider>
  );
}

const persistConfig = {
  key: 'root',
  version: 1,
  storage,
  whitelist: ['auth', 'todos'],         // only persist these
  blacklist: ['ui', 'transient'],      // never persist these
};

const persistedReducer = persistReducer(persistConfig, rootReducer);

import sessionStorage from 'redux-persist/lib/storage/session';

const settingsPersistConfig = {
  key: 'settings',
  storage,
  version: 1,
};

const authPersistConfig = {
  key: 'auth',
  storage: sessionStorage, // cleared when tab closes
  version: 1,
};

const rootReducer = combineReducers({
  settings: persistReducer(settingsPersistConfig, settingsReducer),
  auth: persistReducer(authPersistConfig, authReducer),
  todos: todosReducer,
});

const persistConfig = {
  key: 'root',
  version: 2,
  storage,
  migrate: createMigrate({
    2: (state) => {
      if (!state) return state;
      return {
        ...state,
        // v1 stored todos as an array; v2 expects { ids, entities }
        todos: { ids: state.todos.map((t) => t.id), entities: Object.fromEntries(state.todos.map((t) => [t.id, t])) },
      };
    },
  }, { debug: process.env.NODE_ENV !== 'production' }),
};

let saveTimer;

store.subscribe(() => {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    try {
      localStorage.setItem('app:state', JSON.stringify(store.getState()));
    } catch (e) {
      console.warn('Persist failed', e);
    }
  }, 500);
});

export const toggleTodo = createAsyncThunk(
  'todos/toggle',
  async (id, { dispatch, rejectWithValue }) => {
    dispatch(todoToggledOptimistic(id)); // optimistic
    try {
      await fetch(`/api/todos/${id}/toggle`, { method: 'POST' });
    } catch {
      dispatch(todoToggledRetry(id));
      return rejectWithValue({ id, message: 'Will retry when online' });
    }
  }
);
